package com.improvedmenus;

import java.awt.*;
import java.util.*;
import javax.swing.*;
import net.runelite.client.ui.PluginPanel;

final class ImprovedMenusPanel extends PluginPanel
{
    private final ProfileStore store;
    private final MenuEngine engine;
    private final JTextArea preview = new JTextArea(9,18);
    private final JLabel status = new JLabel(" ");
    private final javax.swing.Timer timer;

    ImprovedMenusPanel(ProfileStore store, MenuEngine engine, Runnable openSettings, java.util.function.Supplier<String> compatibilityStatus)
    {
        super(true);
        this.store=store; this.engine=engine;
        setLayout(new BorderLayout(0,8));
        JPanel top = new JPanel(new net.runelite.client.ui.DynamicGridLayout(0,1,0,6));
        JPanel general=section("Improved Right-Clicks");
        general.add(help("Customize menus, icons and misclick protection."));
        button(general,"Open Plugin Settings",openSettings);
        top.add(general); top.add(Box.createVerticalStrut(10));
        JPanel actions = section("Settings profiles");
        button(actions,"Profiles",this::profiles); button(actions,"Import/export",this::imports);
        JButton undo = new JButton("Undo"); undo.setMargin(new Insets(3,4,3,4));
        undo.addActionListener(e -> status.setText(store.undo() ? "Undone" : "Nothing to undo")); fullWidth(undo); actions.add(undo);
        top.add(actions); top.add(status);
        for (Component child : top.getComponents()) { if (child instanceof JComponent) { ((JComponent)child).setAlignmentX(Component.LEFT_ALIGNMENT); } }
        add(top,BorderLayout.NORTH);
        preview.setEditable(false); preview.setLineWrap(true); preview.setWrapStyleWord(true); preview.setText(engine.diagnostics());
        JPanel bottom = new JPanel(new BorderLayout());
        bottom.add(new JLabel("<html>Log in and open a game menu<br>to inspect its options.</html>"),BorderLayout.NORTH);
        bottom.add(new JScrollPane(preview),BorderLayout.CENTER);
        bottom.setVisible(false);
        JButton diagnostics = new JButton("Show diagnostics");
        fullWidth(diagnostics);
        diagnostics.addActionListener(e -> {
            boolean show = !bottom.isVisible();
            bottom.setVisible(show);
            diagnostics.setText(show ? "Hide diagnostics" : "Show diagnostics");
            revalidate(); repaint();
        });
        top.add(diagnostics);
        add(bottom,BorderLayout.CENTER);
        timer = new javax.swing.Timer(500,e -> { if (isShowing()) { if(bottom.isVisible()) { preview.setText(engine.diagnostics()+"\n\n"+compatibilityStatus.get()); } } });
        timer.start();
    }
    private static JPanel section(String title)
    {
        JPanel panel=new JPanel(new net.runelite.client.ui.DynamicGridLayout(0,1,0,5));
        panel.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createTitledBorder(title),BorderFactory.createEmptyBorder(4,6,6,6)));
        panel.setAlignmentX(Component.LEFT_ALIGNMENT); return panel;
    }
    private static String wrapped(String text) { return "<html><body style='width: 130px; font-weight: normal'>"+text.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")+"</body></html>"; }
    private static JLabel help(String text)
    {
        JLabel label=new JLabel(wrapped(text));
        label.setBorder(BorderFactory.createEmptyBorder(5,0,7,0)); label.setAlignmentX(Component.LEFT_ALIGNMENT); return label;
    }
    private static void fullWidth(JComponent component) { component.setAlignmentX(Component.LEFT_ALIGNMENT); component.setMaximumSize(new Dimension(Integer.MAX_VALUE,component.getPreferredSize().height)); }
    void stop() { timer.stop(); }
    private void button(JPanel parent, String name, Runnable action)
    {
        JButton b = new JButton(name); b.setMargin(new Insets(5,4,5,4)); fullWidth(b); b.addActionListener(e -> run(action)); parent.add(b);
    }
    void run(Runnable action)
    {
        try { action.run(); }
        catch (IllegalArgumentException e) { status.setText("Check settings"); JOptionPane.showMessageDialog(this,e.getMessage(),"Improved Right-Clicks",JOptionPane.ERROR_MESSAGE); }
    }
    private void profiles()
    {
        JPanel contents = new JPanel(new GridLayout(0,1,4,4));
        JTextField name = new JTextField(); JComboBox<String> saved = new JComboBox<>();
        saved.setRenderer(PlainText.renderer());
        saved.setModel(new DefaultComboBoxModel<>(store.names().toArray(new String[0])));
        contents.add(new JLabel("Save current settings as")); contents.add(name);
        button(contents,"Save profile",() -> { store.save(name.getText()); status.setText("Profile saved"); saved.setModel(new DefaultComboBoxModel<>(store.names().toArray(new String[0]))); });
        contents.add(saved);
        button(contents,"Preview and load",() -> {
            Object selected = saved.getSelectedItem();
            if (selected == null) { throw new IllegalArgumentException("Save a profile first"); }
            Map<String,String> values = store.load(selected.toString());
            if (JOptionPane.showConfirmDialog(this,describe(values),"Load profile",JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
            { applySettings(values); }
        });
        JOptionPane.showMessageDialog(this,contents,"Profiles",JOptionPane.PLAIN_MESSAGE);
    }
    private void imports()
    {
        JPanel contents = new JPanel(new BorderLayout(0,6));
        JTextArea json = new JTextArea(store.exportSettings(store.snapshot()),14,24); json.setLineWrap(true);
        contents.add(new JLabel("Copy to export; paste to preview an import."),BorderLayout.NORTH);
        contents.add(new JScrollPane(json),BorderLayout.CENTER);
        JPanel controls = new JPanel(new GridLayout(0,1,4,4));
        JComboBox<String> source = new JComboBox<>(new String[]{"No Examine","No Misclicks In Bank","Item Option Hider","Menu Colorizer","Tool Required","Misclick Guard","No Use Player","Don't Telegrab NPCs","Mouseover Options+"});
        controls.add(source);
        button(controls,"Read existing settings",() -> {
            Map<String,String> values = store.legacyPreview((String)source.getSelectedItem());
            if (values.isEmpty()) { throw new IllegalArgumentException("No explicitly saved settings were found for this plugin"); }
            json.setText(store.exportSettings(values));
            status.setText("Ready to preview");
        });
        button(controls,"Preview and apply",() -> {
            Map<String,String> values = store.previewImport(json.getText());
            if (JOptionPane.showConfirmDialog(this,describe(values),"Apply these settings?",JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
            { applySettings(values); }
        });
        contents.add(controls,BorderLayout.SOUTH);
        JOptionPane.showMessageDialog(this,contents,"Import / export",JOptionPane.PLAIN_MESSAGE);
    }
    void applySettings(Map<String,String> values)
    {
        Map<String,String> before = store.snapshot();
        store.apply(values);
        status.setText(before.equals(store.snapshot()) ? "No changes" : "Settings applied");
    }
    private static JScrollPane describe(Map<String,String> values)
    {
        StringBuilder text = new StringBuilder();
        values.forEach((key,value) -> text.append(SettingsCatalog.ALL.get(key).label).append(": ").append(value).append('\n'));
        JTextArea area = new JTextArea(text.toString(),14,24); area.setEditable(false); area.setLineWrap(true);
        return new JScrollPane(area);
    }
}

package com.improvedmenus;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.*;
import javax.inject.Inject;
import javax.swing.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name="Improved Right-Clicks", description = "Tidy right-click menus with optional misclick protection, item rules, action colours, loot icons, player badges, extra-option indicators and saved profiles.", tags={"menu","bank","inventory","misclick","examine","color"})
public class ImprovedMenusPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ImprovedMenusConfig config;
    @Inject private EventBus eventBus;
    @Inject private ButtonGuard buttons;
    @Inject private MenuEngine engine;
    @Inject private ProfileStore store;
    @Inject private RenameNotice renameNotice;
    @Inject private ClientToolbar toolbar;
    @Inject private OverlayManager overlays;
    @Inject private MenuPresentation presentation;
    @Inject private OptionCountOverlay optionCounts;
    @Inject private ItemIcons itemIcons;
    @Inject private LootFiltersCompatibility lootCompatibility;
    @Inject private LootFiltersMenuPresentation lootMenu;
    @Inject private PlayerMenuBadges playerBadges;
    @Inject private ReleaseNotesNotice releaseNotes;
    private ImprovedMenusPanel panel;
    private NavigationButton navigation;
    private volatile boolean active;
    private Menu colorEditorMenu;
    private MenuEntry colorEditorEntry;
    private Menu colorEditorSubmenu;
    private long lootRevision;

    @Provides ImprovedMenusConfig provideConfig(ConfigManager manager) { return manager.getConfig(ImprovedMenusConfig.class); }
    @Override protected void startUp()
    {
        active=true;
        presentation.setItemIcons(itemIcons);
        if(itemIcons.filters!=null) { itemIcons.filters.reload(); }
        renameNotice.startUp(); releaseNotes.startUp();
        clientThread.invokeLater(() -> { if (active) { engine.reload(); lootCompatibility.refresh(); playerBadges.start(); } });
        buttons.startUp(); eventBus.register(buttons); overlays.add(presentation); overlays.add(optionCounts); overlays.add(playerBadges); presentation.start();
        SwingUtilities.invokeLater(this::updateSidePanel);
    }
    @Override protected void shutDown()
    {
        active=false;
        renameNotice.shutDown(); releaseNotes.shutDown();
        eventBus.unregister(buttons); buttons.shutDown(); overlays.remove(presentation); overlays.remove(optionCounts); overlays.remove(playerBadges);
        clientThread.invoke(() -> { removeColorEditor(); playerBadges.shutdown(); presentation.stop(); lootMenu.stop(); lootCompatibility.reset(); engine.clear(); }); store.clearHistory();
        SwingUtilities.invokeLater(() -> {
            if (panel != null) { panel.stop(); panel=null; }
            if (navigation != null) { toolbar.removeNavigation(navigation); navigation=null; }
        });
    }
    @Subscribe(priority=-0.5f) public void onPostMenuSort(PostMenuSort event)
    { if (!client.isMenuOpen()) { engine.apply(client.getMenu()); } }
    @Subscribe(priority=-1) public void onClientTick(ClientTick event)
    {
        if (!active || client.getGameState() != GameState.LOGGED_IN) return;
        if (!client.isMenuOpen()) engine.applyTargetProtections(client.getMenu());
    }
    @Subscribe public void onGameTick(GameTick event)
    {
        if (!active) return;
        lootCompatibility.refresh();
        long revision=lootCompatibility.revision();
        if (revision!=lootRevision)
        {
            lootRevision=revision;
            if (client.isMenuOpen()) decorateMenu();
        }
    }
    @Subscribe(priority=-2) public void onMenuOpened(MenuOpened event)
    {
        playerBadges.clear(); presentation.stop(); lootMenu.stop();
        engine.applyOpened(client.getMenu());
        decorateMenu();
        if (config.colorPicker() && client.isKeyPressed(KeyCode.KC_SHIFT)) { addColorEditor(client.getMenu()); }
    }
    @Subscribe public void onConfigChanged(ConfigChanged event)
    {
        if (ImprovedMenusConfig.GROUP.equals(event.getGroup()))
        {
            if(itemIcons.filters!=null && (event.getKey().equals(FilterIcons.KEY) || event.getKey().equals(FilterIcons.BACKUP))) { itemIcons.filters.reload(); }
            clientThread.invokeLater(() -> { if (active) { playerBadges.clear(); presentation.stop(); lootMenu.stop(); lootCompatibility.reset(); lootCompatibility.refresh(); engine.reload(); if(client.isMenuOpen()) decorateMenu(); } });
            if (event.getKey().equals("hideSidePanel")) { SwingUtilities.invokeLater(this::updateSidePanel); }
        }
        else if ("loot-filters".equals(event.getGroup())) refreshLootFilter();
    }
    @Subscribe public void onProfileChanged(net.runelite.client.events.ProfileChanged event) { clientThread.invokeLater(() -> { if (active) { playerBadges.clear(); releaseNotes.showIfLoggedIn(); } }); refreshLootFilter(); if(itemIcons.filters!=null) { itemIcons.filters.reload(); } }
    @Subscribe public void onPluginChanged(net.runelite.client.events.PluginChanged event)
    { if ("Loot Filters".equals(event.getPlugin().getName())) refreshLootFilter(); }
    @Subscribe public void onPluginMessage(net.runelite.client.events.PluginMessage event)
    { if ("loot-filters".equals(event.getNamespace()) && "filter-reloaded".equals(event.getName())) refreshLootFilter(); }
    private void refreshLootFilter()
    {
        clientThread.invokeLater(() -> {
            if (!active) return;
            playerBadges.clear(); presentation.stop(); lootMenu.stop(); lootCompatibility.reset(); lootCompatibility.refresh();
            if (client.isMenuOpen()) decorateMenu();
        });
    }
    private void decorateMenu() {
        // Unwind in reverse order before reapplying asynchronously refreshed icons/colors.
        playerBadges.clear(); presentation.stop(); lootMenu.stop();
        lootCompatibility.beginMenu();
        try { lootMenu.apply(client.getMenu()); presentation.decorate(client.getMenu()); playerBadges.decorate(client.getMenu()); }
        finally { lootCompatibility.endMenu(); }
    }
    @Subscribe public void onBeforeMenuRender(BeforeMenuRender event)
    { if (active && client.isMenuOpen()) { engine.highlightHovered(client.getMenu()); } }
    private void updateSidePanel()
    {
        if (!active || config.hideSidePanel())
        {
            if (navigation != null) { toolbar.removeNavigation(navigation); navigation=null; }
            if (panel != null) { panel.stop(); panel=null; }
        }
        else if (navigation == null)
        {
            panel=new ImprovedMenusPanel(store,engine,this::openSettings,lootCompatibility::status);
            navigation=NavigationButton.builder().tooltip("Improved Right-Clicks").icon(icon()).priority(6).panel(panel).build();
            toolbar.addNavigation(navigation);
        }
    }
    private void openSettings()
    {
        net.runelite.client.ui.overlay.Overlay target = new net.runelite.client.ui.overlay.Overlay(this) {
            @Override public java.awt.Dimension render(Graphics2D graphics) { return null; }
        };
        eventBus.post(new net.runelite.client.events.OverlayMenuClicked(
            new net.runelite.client.ui.overlay.OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG,
                net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE,"Improved Right-Clicks"),target));
    }
    @Subscribe public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN) { playerBadges.clear(); presentation.stop(); lootMenu.stop(); lootCompatibility.reset(); buttons.reset(); engine.clear(); }
        else { renameNotice.showIfLoggedIn(); releaseNotes.showIfLoggedIn(); }
    }
    @Subscribe public void onFocusChanged(FocusChanged event) { if (!event.isFocused()) { clientThread.invoke(buttons::reset); } }

    private void addColorEditor(Menu menu)
    {
        removeColorEditor();
        // Local UI callbacks only. Game actions are never replayed.
        Set<String> seen = new LinkedHashSet<>();
        java.util.List<String[]> choices = new ArrayList<>();
        collect(menu,"",seen,choices,0);
        if (choices.isEmpty()) { return; }
        colorEditorMenu=menu;
        colorEditorEntry=menu.createMenuEntry(0).setOption("Menu colors").setTarget("").setType(MenuAction.RUNELITE);
        Menu sub=colorEditorEntry.createSubMenu(); colorEditorSubmenu=sub;
        for (String[] choice : choices)
        {
            String target=choice[0], option=choice[1];
            sub.createMenuEntry(-1).setOption(option).setTarget(target).setType(MenuAction.RUNELITE).onClick(e -> {
                SwingUtilities.invokeLater(() -> {
                    if (!active) { return; }
                    String old=engine.color(target,option);
                    Color color=JColorChooser.showDialog(panel,"Color " + option + " " + target,old == null ? SettingsCatalog.colorOrDefault(config.defaultPickerColor(),Color.GREEN) : new Color(Integer.parseInt(old,16)));
                    if (color != null && active) { saveColor(target,option,String.format("#%06x",color.getRGB() & 0xffffff)); }
                });
            });
            sub.createMenuEntry(-1).setOption("Reset " + option).setTarget(target).setType(MenuAction.RUNELITE).onClick(e -> saveColor(target,option,null));
        }
    }
    private void removeColorEditor()
    {
        if (colorEditorMenu != null && colorEditorEntry != null && colorEditorEntry.getSubMenu() == colorEditorSubmenu
            && colorEditorEntry.getType() == MenuAction.RUNELITE && colorEditorEntry.getOption().equals("Menu colors"))
        {
            MenuEntry[] entries=colorEditorMenu.getMenuEntries();
            MenuEntry[] kept=Arrays.stream(entries).filter(e -> e != colorEditorEntry).toArray(MenuEntry[]::new);
            if (kept.length != entries.length) { colorEditorMenu.setMenuEntries(kept); }
        }
        colorEditorMenu=null; colorEditorEntry=null; colorEditorSubmenu=null;
    }
    private void collect(Menu menu,String inherited,Set<String> seen,java.util.List<String[]> choices,int depth)
    {
        if (depth > 8) { return; }
        for (MenuEntry entry : menu.getMenuEntries())
        {
            String target=MenuRules.plain(entry.getTarget()); if (target.isEmpty()) { target=inherited; }
            String option=MenuRules.plain(entry.getOption());
            if (entry.getSubMenu() != null) { collect(entry.getSubMenu(),target,seen,choices,depth+1); }
            else if (!target.isEmpty() && !target.contains(":") && !target.contains(";") && !target.contains("*")
                && !option.contains(":") && !option.contains(";") && !option.contains("*") && entry.getType() != MenuAction.CANCEL
                && choices.size() < 40 && seen.add(target + "\n" + option)) { choices.add(new String[]{target,option}); }
        }
    }
    private void saveColor(String target,String option,String color)
    {
        if (!active) { return; }
        String prefix=target + ":" + option + ":";
        java.util.List<String> values = new ArrayList<>();
        for (String raw : config.colors().split(";"))
        { if (!raw.trim().isEmpty() && !raw.trim().regionMatches(true,0,prefix,0,prefix.length())) { values.add(raw.trim()); } }
        if (color != null) { values.add(prefix + color); }
        try { store.apply(Collections.singletonMap("colors",String.join(";",values))); }
        catch (IllegalArgumentException e) { SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(panel,e.getMessage(),"Menu colors",JOptionPane.ERROR_MESSAGE)); }
    }
    private static BufferedImage icon()
    {
        BufferedImage image=new BufferedImage(48,48,BufferedImage.TYPE_INT_ARGB);
        Graphics2D g=image.createGraphics(); g.setColor(new Color(38,42,49)); g.fillRoundRect(2,2,44,44,10,10);
        g.setColor(new Color(223,174,65)); for (int y=12;y<40;y+=10) { g.fillRoundRect(10,y,28,4,3,3); } g.dispose(); return image;
    }
}

package com.improvedmenus;

import com.google.gson.Gson;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;

/** Our own assignments; never writes Loot Filters configuration or files. */
@Singleton
class ItemIcons
{
    static final String KEY="itemIconAssignments", BACKUP="itemIconBackup";
    enum Kind { HEART, STAR, DIAMOND, CURRENT_ITEM, ITEM, SPRITE, IMAGE }
    static final class Assignment
    {
        String image; String name; int itemId=-1; Kind kind; int iconId; int spriteIndex;
        String key() { return itemId>=0 ? "id:"+itemId : "name:"+name.toLowerCase(Locale.ROOT); }
        @Override public String toString() { return (itemId>=0 ? "Item #"+itemId : name)+" — "+kind+(kind==Kind.ITEM || kind==Kind.SPRITE ? " #"+iconId : ""); }
    }
    @Inject ConfigManager configs;
    @Inject Gson gson;
    @Inject ItemManager items;
    @Inject SpriteManager sprites;
    @Inject FilterIcons filters;
    private final Map<String,BufferedImage> imageCache=new LinkedHashMap<>();
    private final Map<Kind,BufferedImage> builtins=new EnumMap<>(Kind.class);
    private String cached;
    private List<Assignment> assignments=Collections.emptyList();
    synchronized List<Assignment> snapshot()
    {
        String raw=configs.getConfiguration(ImprovedMenusConfig.GROUP,KEY);
        if(!Objects.equals(raw,cached))
        {
            try { assignments=parse(raw==null ? "[]" : raw); }
            catch(IllegalArgumentException e) { assignments=Collections.emptyList(); }
            cached=raw;
        }
        return new ArrayList<>(assignments);
    }
    List<Assignment> parse(String raw)
    {
        if(raw==null || raw.length()>200000) { throw new IllegalArgumentException("Icon data is too large."); }
        try
        {
            Assignment[] data=gson.fromJson(raw,Assignment[].class);
            if(data==null || data.length>500) { throw new IllegalArgumentException("Use at most 500 assignments."); }
            LinkedHashMap<String,Assignment> unique=new LinkedHashMap<>();
            for(Assignment a:data)
            {
                if(a==null || a.kind==null || a.itemId < -1 || a.itemId>100000 || a.iconId<0 || a.iconId>100000 || a.spriteIndex<0 || a.spriteIndex>255
                    || (a.itemId<0 && (a.name==null || a.name.trim().isEmpty() || a.name.length()>120 || a.name.contains("<") || a.name.contains(">"))))
                { throw new IllegalArgumentException("Invalid icon assignment."); }
                if(a.kind==Kind.IMAGE) { IconImages.decode(a.image); }
                if(a.name!=null) { a.name=a.name.trim(); }
                unique.put(a.key(),a);
            }
            return new ArrayList<>(unique.values());
        }
        catch(com.google.gson.JsonParseException e) { throw new IllegalArgumentException("Invalid icon JSON."); }
    }
    String export() { return gson.toJson(snapshot()); }
    void save(List<Assignment> next)
    {
        String json=gson.toJson(next); parse(json);
        configs.setConfiguration(ImprovedMenusConfig.GROUP,BACKUP,export());
        configs.setConfiguration(ImprovedMenusConfig.GROUP,KEY,json);
    }
    void undo()
    {
        String before=configs.getConfiguration(ImprovedMenusConfig.GROUP,BACKUP);
        if(before!=null) { save(parse(before)); }
    }
    Assignment find(int id)
    {
        List<Assignment> entries=snapshot();
        for(Assignment a:entries) { if(a.itemId==id) { return a; } }
        if(entries.isEmpty()) { return null; }
        String name=items.getItemComposition(id).getName();
        for(Assignment a:entries) { if(a.itemId<0 && a.name.equalsIgnoreCase(name)) { return a; } }
        return null;
    }
    BufferedImage image(Assignment a,int id)
    {
        if(a==null) { return null; }
        if(a.kind==Kind.CURRENT_ITEM || a.kind==Kind.ITEM) { return items.getImage(a.kind==Kind.CURRENT_ITEM ? id : a.iconId); }
        if(a.kind==Kind.IMAGE) {
            if(imageCache.size()>256) imageCache.clear();
            return imageCache.computeIfAbsent(a.image,IconImages::decode);
        }
        if(a.kind==Kind.SPRITE) { try { return sprites.getSprite(a.iconId,a.spriteIndex); } catch(IndexOutOfBoundsException e) { return null; } }
        if(builtins.containsKey(a.kind)) { return builtins.get(a.kind); }
        BufferedImage result=new BufferedImage(17,15,BufferedImage.TYPE_INT_ARGB);
        Graphics2D g=result.createGraphics();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);
            if(a.kind==Kind.HEART) { g.setColor(new Color(255,105,110)); g.fillOval(1,1,8,8); g.fillOval(8,1,8,8); g.fillPolygon(new int[]{1,16,8},new int[]{6,6,14},3); }
            else if(a.kind==Kind.DIAMOND) { g.setColor(Color.CYAN); g.fillPolygon(new int[]{8,15,8,1},new int[]{0,7,14,7},4); }
            else { g.setColor(new Color(255,210,60)); Polygon star=new Polygon(); for(int i=0;i<10;i++) { double angle=-Math.PI/2+i*Math.PI/5; double radius=i%2==0 ? 7 : 3; star.addPoint(8+(int)(Math.cos(angle)*radius),7+(int)(Math.sin(angle)*radius)); } g.fillPolygon(star); }
        }
        finally { g.dispose(); }
        builtins.put(a.kind,result);
        return result;
    }
}

package com.improvedmenus;

import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.function.Consumer;
import java.util.function.Supplier;

/** Client-thread-owned cache of independent images supplied asynchronously by Loot Filters. */
final class LootFilterImageCache {
    private static final int LIMIT=128;
    private final Map<Map<String,Object>,Entry> entries=new LinkedHashMap<>(16,.75f,true);
    private final Consumer<Runnable> clientThread;
    private long generation,revision;
    private static final class Entry {
        BufferedImage image;
        boolean complete;
        long requested=System.nanoTime();
    }
    LootFilterImageCache(Consumer<Runnable> clientThread) { this.clientThread=clientThread; }
    long revision() { return revision; }
    void clear() { generation++;revision++;entries.clear(); }
    BufferedImage get(Map<String,Object> key,Supplier<?> provider) {
        Entry existing=entries.get(key);
        if(existing!=null && (existing.image!=null || System.nanoTime()-existing.requested<(existing.complete?5_000_000_000L:10_000_000_000L))) return existing.image;
        Entry entry=new Entry();entries.put(key,entry);
        if(entries.size()>LIMIT) entries.remove(entries.keySet().iterator().next());
        long version=generation;
        try {
            Object supplied=provider.get();
            if(!(supplied instanceof CompletableFuture)) { entry.complete=true;return null; }
            ((CompletableFuture<?>)supplied).whenComplete((image,error)->clientThread.accept(()->{
                if(version!=generation || entries.get(key)!=entry) return;
                entry.complete=true;
                if(error==null && image instanceof BufferedImage) {
                    BufferedImage loaded=(BufferedImage)image;
                    if(loaded.getWidth()<=1024 && loaded.getHeight()<=1024) {
                        // Retain menu-sized pixels, not up to 128 full-size file images.
                        if(loaded.getWidth()>17 || loaded.getHeight()>15) {
                            entry.image=new BufferedImage(17,15,BufferedImage.TYPE_INT_ARGB);
                            var graphics=entry.image.createGraphics();
                            try { graphics.drawImage(loaded,0,0,17,15,null); }
                            finally { graphics.dispose(); }
                        } else entry.image=loaded;
                    }
                }
                revision++;
            }));
        } catch(RuntimeException error) { entry.complete=true; }
        return entry.image;
    }
}

package com.improvedmenus;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

/** Optional resolved-display messages; never reads another plugin's files or implementation classes. */
@Singleton
class LootFiltersCompatibility {
    private final Client client;
    private final ImprovedMenusConfig config;
    private final PluginManager plugins;
    private final EventBus events;
    private final LootFilterImageCache images;
    private boolean collecting,enabled;
    private final Map<Tile,Map<Integer,Result>> menuResults=new IdentityHashMap<>();
    private volatile String status="Open a Take menu to check Loot Filters compatibility.";
    @Inject LootFiltersCompatibility(Client client,ClientThread clientThread,ImprovedMenusConfig config,PluginManager plugins,EventBus events) {
        this.client=client;this.config=config;this.plugins=plugins;this.events=events;
        images=new LootFilterImageCache(clientThread::invokeLater);
    }
    static final class Result {
        final BufferedImage image;
        final boolean itemIcon,hidden,hideOverlay;
        final int menuSort;
        final Color menuColor;
        final Map<String,Object> icon;
        final Supplier<?> provider;
        Result(BufferedImage image,boolean itemIcon) { this(image,itemIcon,false,false,0,null); }
        Result(BufferedImage image,boolean itemIcon,boolean hidden,boolean hideOverlay,int menuSort,Color menuColor) {
            this(image,itemIcon,hidden,hideOverlay,menuSort,menuColor,null,null);
        }
        Result(BufferedImage image,boolean itemIcon,boolean hidden,boolean hideOverlay,int menuSort,Color menuColor,Map<String,Object> icon,Supplier<?> provider) {
            this.image=image;this.itemIcon=itemIcon;this.hidden=hidden;this.hideOverlay=hideOverlay;
            this.menuSort=menuSort;this.menuColor=menuColor;this.icon=icon;this.provider=provider;
        }
        boolean hasIcon() { return !hidden && !hideOverlay && (image!=null || icon!=null && provider!=null); }
    }
    String status() { return status; }
    long revision() { return images.revision(); }
    void refresh() {
        if(!client.isClientThread()) return;
        boolean running=false;
        if(config.lootFiltersCompatibility() || config.useLootFiltersInMenu())
            for(Plugin plugin:plugins.getPlugins())
                if("Loot Filters".equals(plugin.getName()) && plugins.isPluginActive(plugin)) { running=true;break; }
        if(running!=enabled) { images.clear();endMenu();enabled=running; }
        if(!config.lootFiltersCompatibility() && !config.useLootFiltersInMenu()) status="Loot Filters compatibility is off.";
        else if(!running) status="Enable Loot Filters to use its resolved display settings.";
    }
    void reset() { endMenu();images.clear();enabled=false;status="Open a Take menu to check Loot Filters compatibility."; }
    void beginMenu() { refresh();menuResults.clear();collecting=true; }
    void endMenu() { menuResults.clear();collecting=false; }
    Result findIcon(MenuEntry entry) { Result result=find(entry);image(result);return result; }
    BufferedImage image(Result result) {
        if(result==null || !result.hasIcon() || !client.isClientThread()) return null;
        if(result.image!=null) return result.image;
        return images.get(result.icon,result.provider);
    }
    Result find(MenuEntry entry) {
        if(!enabled || !client.isClientThread()) return null;
        WorldView view=client.getWorldView(entry.getWorldViewId());
        if(view==null || view.getScene()==null) return null;
        Tile[][][] tiles=view.getScene().getTiles();
        int plane=view.getPlane(),x=entry.getParam0(),y=entry.getParam1();
        if(tiles==null || plane<0 || plane>=tiles.length || tiles[plane]==null || x<0 || x>=tiles[plane].length
            || tiles[plane][x]==null || y<0 || y>=tiles[plane][x].length || tiles[plane][x][y]==null) return null;
        if(!collecting) return request(view,x,y,plane,entry.getIdentifier());
        Map<Integer,Result> results=menuResults.computeIfAbsent(tiles[plane][x][y],ignored->new HashMap<>());
        if(!results.containsKey(entry.getIdentifier())) results.put(entry.getIdentifier(),request(view,x,y,plane,entry.getIdentifier()));
        return results.get(entry.getIdentifier());
    }
    Result request(WorldView view,int x,int y,int plane,int itemId) {
        Map<String,Object> data=new HashMap<>();
        data.put("worldViewId",view.getId());data.put("x",view.getBaseX()+x);data.put("y",view.getBaseY()+y);data.put("z",plane);data.put("itemId",itemId);
        events.post(new PluginMessage("loot-filters","resolved-display-request-v1",data));
        Result result=decode(data,itemId);
        status=result!=null?"Connected to Loot Filters. Icons, menu behavior and colors use their separate settings.":
            data.containsKey("status")?"Loot Filters has no ready, unambiguous display settings for this item.":
            "This Loot Filters version does not provide resolved display settings. A compatible provider update is required.";
        return result;
    }
    static Result decode(Map<String,Object> data,int itemId) {
        if(!"ok".equals(data.get("status")) || !(data.get("display") instanceof Map)) return null;
        Map<?,?> display=(Map<?,?>)data.get("display");
        if(!(display.get("hidden") instanceof Boolean) || !(display.get("hideOverlay") instanceof Boolean)
            || !(display.get("menuSort") instanceof Integer) || display.get("menuTextColor")!=null && !(display.get("menuTextColor") instanceof Color)) return null;
        Map<String,Object> descriptor=null;Supplier<?> provider=null;boolean same=false;
        if(display.get("icon")!=null) {
            if(!(display.get("icon") instanceof Map)) return null;
            Map<?,?> icon=(Map<?,?>)display.get("icon");
            Object type=icon.get("type");if(!(type instanceof String)) return null;
            if(icon.get("getImage") instanceof Supplier) provider=(Supplier<?>)icon.get("getImage");
            descriptor=new HashMap<>();descriptor.put("type",type);
            for(String key:Arrays.asList("id","index","quantity","height","filename")) {
                Object value=icon.get(key);
                if(value!=null && !(value instanceof Integer) && !(key.equals("filename") && value instanceof String)) return null;
                if(value!=null) descriptor.put(key,value);
            }
            descriptor=Collections.unmodifiableMap(descriptor);
            same=("item".equals(type) || "current-item".equals(type)) && Integer.valueOf(itemId).equals(icon.get("id"));
        }
        return new Result(null,same,(Boolean)display.get("hidden"),(Boolean)display.get("hideOverlay"),
            (Integer)display.get("menuSort"),(Color)display.get("menuTextColor"),descriptor,provider);
    }
}

package com.improvedmenus;

import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;

/** Optional presentation of opened Take menus. Never removes entries or changes left-click actions. */
@Singleton
final class LootFiltersMenuPresentation {
    @Inject private ImprovedMenusConfig config;
    @Inject private LootFiltersCompatibility compatibility;
    private final Map<MenuEntry, TargetEdit> colors = new IdentityHashMap<>();
    private Menu sortedMenu;
    private MenuEntry[] originalOrder, sortedOrder;
    private final Map<MenuEntry, Identity> identities = new IdentityHashMap<>();

    void apply(Menu menu) {
        stop();
        if(menu==null || !config.useLootFiltersInMenu()) return;
        MenuEntry[] entries=menu.getMenuEntries();
        List<Integer> slots=new ArrayList<>();
        List<Ranked> rows=new ArrayList<>();
        for(int i=0;i<entries.length;i++) {
            MenuEntry entry=entries[i];
            if(!isTake(entry) || entry.getSubMenu()!=null) continue;
            LootFiltersCompatibility.Result display=compatibility.find(entry);
            if(display==null) continue;
            slots.add(i); rows.add(new Ranked(entry,display));
            // Hidden-row recoloring belongs to Loot Filters' own preference, not DisplayConfig.
            if(config.lootFiltersMenuColors() && !display.hidden && display.menuColor!=null) {
                String before=entry.getTarget();
                String after=String.format("<col=%06x>",display.menuColor.getRGB() & 0xffffff)
                    + before.replaceAll("</?col(?:=[^>]*)?>", "") + "</col>";
                if(!before.equals(after)) {
                    colors.put(entry,new TargetEdit(entry,before,after)); entry.setTarget(after);
                }
            }
        }
        // RuneLite draws the array in reverse. Keep every non-Take / unresolved row in its original slot.
        rows.sort((a,b) -> {
            int priority=Boolean.compare(b.deprioritized,a.deprioritized);
            return priority!=0 ? priority : Integer.compare(a.sort,b.sort);
        });
        MenuEntry[] ordered=entries.clone();
        for(int i=0;i<slots.size();i++) ordered[slots.get(i)]=rows.get(i).entry;
        if(!sameOrder(entries,ordered)) {
            sortedMenu=menu; originalOrder=entries.clone(); sortedOrder=ordered.clone();
            for(MenuEntry entry:entries) identities.put(entry,new Identity(entry));
            menu.setMenuEntries(ordered);
        }
    }

    void stop() {
        colors.forEach((entry,edit) -> { if(edit.identity.matches(entry) && edit.after.equals(entry.getTarget())) entry.setTarget(edit.before); });
        colors.clear();
        if(sortedMenu!=null && sameOrder(sortedMenu.getMenuEntries(),sortedOrder)
                && identities.entrySet().stream().allMatch(e -> e.getValue().matches(e.getKey()))) {
            sortedMenu.setMenuEntries(originalOrder);
        }
        sortedMenu=null; originalOrder=null; sortedOrder=null; identities.clear();
    }

    static boolean isTake(MenuEntry entry) {
        MenuAction type=entry.getType();
        return (type==MenuAction.GROUND_ITEM_FIRST_OPTION || type==MenuAction.GROUND_ITEM_SECOND_OPTION
            || type==MenuAction.GROUND_ITEM_THIRD_OPTION || type==MenuAction.GROUND_ITEM_FOURTH_OPTION
            || type==MenuAction.GROUND_ITEM_FIFTH_OPTION) && "Take".equals(MenuRules.plain(entry.getOption()));
    }
    private static boolean sameOrder(MenuEntry[] a,MenuEntry[] b) {
        if(a.length!=b.length) return false;
        for(int i=0;i<a.length;i++) if(a[i]!=b[i]) return false;
        return true;
    }
    private static final class Ranked {
        final MenuEntry entry;
        final int sort;
        final boolean deprioritized;
        Ranked(MenuEntry entry,LootFiltersCompatibility.Result display) {
            this.entry=entry; sort=display.menuSort; deprioritized=entry.isDeprioritized();
        }
    }
    private static final class TargetEdit {
        final Identity identity;
        final String before,after;
        TargetEdit(MenuEntry entry,String before,String after) { identity=new Identity(entry); this.before=before; this.after=after; }
    }
    private static final class Identity {
        final MenuAction type;
        final int id,x,y,worldView;
        Identity(MenuEntry entry) { type=entry.getType(); id=entry.getIdentifier(); x=entry.getParam0(); y=entry.getParam1(); worldView=entry.getWorldViewId(); }
        boolean matches(MenuEntry entry) { return type==entry.getType() && id==entry.getIdentifier() && x==entry.getParam0() && y==entry.getParam1() && worldView==entry.getWorldViewId(); }
    }
}

package com.improvedmenus;

import java.util.*;
import java.util.regex.*;

/** Conservative format reader, not a replacement for Loot Filters' evaluator. */
final class LootIconImport
{
    static List<ItemIcons.Assignment> parse(String source)
    {
        if(source.length()>1000000) { throw new IllegalArgumentException("Filter is too large."); }
        // Remove comments without treating comment markers inside strings as comments.
        String clean=source;
        StringBuilder stripped=new StringBuilder();
        boolean quote=false;
        for(int i=0;i<clean.length();i++)
        {
            char c=clean.charAt(i);
            if(c=='"' && (i==0 || clean.charAt(i-1)!='\\')) { quote=!quote; }
            if(!quote && c=='/' && i+1<clean.length() && clean.charAt(i+1)=='/') { while(i<clean.length() && clean.charAt(i)!='\n') { i++; } stripped.append('\n'); continue; }
            if(!quote && c=='/' && i+1<clean.length() && clean.charAt(i+1)=='*') { int end=clean.indexOf("*/",i+2); if(end<0) { throw new IllegalArgumentException("Unclosed comment."); } i=end+1; continue; }
            stripped.append(c);
        }
        clean=stripped.toString();
        if(Pattern.compile("(?m)^\\s*#").matcher(clean).find()) { throw new IllegalArgumentException("This filter uses directives/macros. Automatic icon import is not supported; assign its icons manually. Nothing was changed."); }
        Pattern block=Pattern.compile("\\G\\s*(meta|rule|if|apply)\\s*(?:\\(([^{}]*)\\))?\\s*\\{([^{}]*)\\}");
        Matcher m=block.matcher(clean); int end=0;
        LinkedHashMap<String,ItemIcons.Assignment> result=new LinkedHashMap<>();
        while(m.find())
        {
            end=m.end();
            if(m.group(1).equals("meta")) { continue; }
            if(m.group(1).equals("apply")) { throw unsupported(); }
            String condition=m.group(2);
            if(condition==null) { throw unsupported(); }
            Matcher selector=Pattern.compile("\\s*(id|name)\\s*:\\s*(.*?)\\s*",Pattern.DOTALL).matcher(condition);
            if(!selector.matches()) { throw unsupported(); }
            String values=selector.group(2).trim();
            if(values.startsWith("[") && values.endsWith("]")) { values=values.substring(1,values.length()-1); }
            List<String> keys=new ArrayList<>();
            Matcher value=Pattern.compile(selector.group(1).equals("id") ? "\\G\\s*(\\d+)\\s*(?:,|$)" : "\\G\\s*\"([^\"*?\\\\]+)\"\\s*(?:,|$)").matcher(values);
            int used=0;
            while(value.find()) { keys.add(value.group(1)); used=value.end(); }
            if(keys.isEmpty() || used!=values.length()) { throw unsupported(); }
            Matcher icon=Pattern.compile("(?:^|(?<=;))\\s*icon\\s*=\\s*(CurrentItem|Item|Sprite)\\s*\\(([^()]*)\\)\\s*;",Pattern.DOTALL).matcher(m.group(3));
            if(!icon.find()) { throw new IllegalArgumentException("Every rule must have an explicit CurrentItem(), Item(id), or Sprite(id,index) icon. File icons and rules without icons cannot be transferred safely."); }
            String type=icon.group(1), args=icon.group(2).trim();
            int iconId=0,index=0;
            if(type.equals("CurrentItem")) { if(!args.isEmpty()) { throw unsupported(); } }
            else
            {
                if(!args.matches(type.equals("Item") ? "\\d+" : "\\d+\\s*,\\s*\\d+")) { throw unsupported(); }
                String[] parts=args.split("\\s*,\\s*");
                try { iconId=Integer.parseInt(parts[0]); if(parts.length>1) { index=Integer.parseInt(parts[1]); } }
                catch(NumberFormatException e) { throw unsupported(); }
            }
            if(icon.find()) { throw new IllegalArgumentException("Multiple icon assignments in a rule are not supported."); }
            for(String key:keys)
            {
                ItemIcons.Assignment a=new ItemIcons.Assignment();
                try { if(selector.group(1).equals("id")) { a.itemId=Integer.parseInt(key); } else { a.name=key; } }
                catch(NumberFormatException e) { throw unsupported(); }
                a.kind=type.equals("CurrentItem") ? ItemIcons.Kind.CURRENT_ITEM : type.equals("Item") ? ItemIcons.Kind.ITEM : ItemIcons.Kind.SPRITE;
                a.iconId=iconId; a.spriteIndex=index;
                if(a.itemId>100000 || iconId>100000 || index>255 || result.size()>=500) { throw unsupported(); }
                // Terminal rules use the first match. Mixed name/id selectors can overlap.
                if(!result.isEmpty() && result.values().iterator().next().itemId>=0 != (a.itemId>=0)) { throw new IllegalArgumentException("Mixed name and ID rules need manual review; nothing was imported."); }
                result.putIfAbsent(a.key(),a);
            }
        }
        if(!clean.substring(end).trim().isEmpty() || result.isEmpty()) { throw unsupported(); }
        return new ArrayList<>(result.values());
    }
    private static IllegalArgumentException unsupported()
    { return new IllegalArgumentException("Only terminal rules with exact item IDs or names are supported. Conditional, wildcard, inherited or malformed rules require manual assignments. Nothing was changed."); }
}

package com.improvedmenus;

import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

@Singleton
final class MenuEngine
{
    private static final Set<MenuAction> OBJECTS = EnumSet.of(MenuAction.GAME_OBJECT_FIRST_OPTION,
        MenuAction.GAME_OBJECT_SECOND_OPTION, MenuAction.GAME_OBJECT_THIRD_OPTION,
        MenuAction.GAME_OBJECT_FOURTH_OPTION, MenuAction.GAME_OBJECT_FIFTH_OPTION);
    private static final Set<MenuAction> ITEMS = EnumSet.of(MenuAction.CC_OP, MenuAction.CC_OP_LOW_PRIORITY,
        MenuAction.WIDGET_TARGET, MenuAction.WIDGET_TARGET_ON_WIDGET,
        MenuAction.GROUND_ITEM_FIRST_OPTION, MenuAction.GROUND_ITEM_SECOND_OPTION,
        MenuAction.GROUND_ITEM_THIRD_OPTION, MenuAction.GROUND_ITEM_FOURTH_OPTION, MenuAction.GROUND_ITEM_FIFTH_OPTION,
        MenuAction.EXAMINE_ITEM_GROUND);

    @Inject private Client client;
    @Inject private ImprovedMenusConfig config;
    @Inject private RevealState reveal;
    @Inject private TargetProtections targets;
    private List<MenuRules.Rule> itemRules = Collections.emptyList();
    private List<MenuRules.Rule> colors = Collections.emptyList();
    private List<MenuRules.Rule> exceptions = Collections.emptyList();
    private String validation = "";
    private volatile String diagnostics = "Hover an item or open a menu to preview changes.";
    private final IdentityHashMap<MenuEntry,ColorEdit> ownedColors = new IdentityHashMap<>();

    void reload()
    {
        restoreColors();
        // Invalid edits fail open instead of leaving invisible stale rules active.
        List<String> errors = new ArrayList<>();
        try { itemRules = MenuRules.parseItems(config.itemRules()); }
        catch (IllegalArgumentException e) { itemRules = Collections.emptyList(); errors.add(e.getMessage()); }
        try { colors = MenuRules.parseColors(config.colors()); }
        catch (IllegalArgumentException e) { colors = Collections.emptyList(); errors.add(e.getMessage()); }
        try { exceptions = MenuRules.parseExceptions(config.exceptions()); }
        catch (IllegalArgumentException e) { exceptions = Collections.emptyList(); errors.add(e.getMessage()); }
        validation = String.join("\n", errors);
    }
    String diagnostics() { return diagnostics; }
    void clear() { restoreColors(); diagnostics = "Menu preview cleared."; }
    private void restoreColors()
    {
        ownedColors.forEach((entry,edit) -> {
            if (entry.getOption().equals(edit.after) && MenuRules.plain(entry.getTarget()).equals(edit.target)
                && entry.getType() == edit.type && entry.getIdentifier() == edit.identifier) { entry.setOption(edit.before); }
        });
        ownedColors.clear();
    }
    void highlightHovered(Menu menu)
    {
        // Release the previous hover before finding this frame's row. Only change
        // entries whose identity and text still match our own decoration.
        ownedColors.forEach((entry,edit) -> {
            if (edit.matches(entry)) { entry.setOption(edit.colored); edit.after=edit.colored; }
        });
        if (!config.enableColors() || !config.yellowHover() || menu == null) { return; }
        MenuEntry hovered=hovered(menu);
        ColorEdit edit=ownedColors.get(hovered);
        if (edit != null && edit.matches(hovered))
        {
            // Native rendering supplies yellow. Keep image tags and target colors.
            edit.after=edit.colored.replaceAll("</?col(?:=[^>]*)?>", "");
            hovered.setOption(edit.after);
        }
    }
    private MenuEntry hovered(Menu menu)
    {
        if (menu.getMenuWidth() <= 0 || menu.getMenuHeight() <= 0) { return null; }
        MenuEntry[] entries=menu.getMenuEntries();
        // Public Menu bounds are valid only while open. The API does not expose
        // which submenu is open, so never use cached child bounds for hit testing.
        Point mouse=client.getMouseCanvasPosition();
        int x=mouse.getX(), y=mouse.getY();
        if (x <= menu.getMenuX() || x >= menu.getMenuX()+menu.getMenuWidth()
            || y <= menu.getMenuY()+18 || y >= menu.getMenuY()+menu.getMenuHeight()) { return null; }
        int scroll=client.isMenuScrollable() ? client.getMenuScroll() : 0;
        for (int i=0;i<entries.length;i++)
        {
            int baseline=menu.getMenuY()+31+(entries.length-1-i-scroll)*15;
            if (y > baseline-13 && y < baseline+3) { return entries[i]; }
        }
        return null;
    }

    void apply(Menu menu)
    { apply(menu,true); }
    void applyOpened(Menu menu)
    { apply(menu,false); }
    private void apply(Menu menu,boolean capture)
    {
        if (menu == null || reveal.isRevealed()) { diagnostics = "Reveal is held: filtering paused."; return; }
        StringBuilder report = new StringBuilder(validation);
        Context context = context();
        int before=menu.getMenuEntries().length;
        apply(menu, "", context, report, 0, capture && client.isKeyPressed(KeyCode.KC_SHIFT));
        if (!capture) { cleanOpenedMenu(menu,report,0); }
        if (capture || before != menu.getMenuEntries().length)
        {
            String result = "Before: " + before + " entries. After: " + menu.getMenuEntries().length + " entries.\n"
                + (report.length() == 0 ? "No changes to this menu." : report.toString());
            diagnostics = capture ? result : diagnostics + "\nOn opening:\n" + result;
        }
    }
    void applyTargetProtections(Menu menu)
    {
        if (menu == null || reveal.isRevealed() || !client.isWidgetSelected()) { return; }
        MenuEntry[] entries = menu.getMenuEntries();
        List<MenuEntry> kept = new ArrayList<>(entries.length);
        StringBuilder report = new StringBuilder();
        for (MenuEntry entry : entries)
        {
            String reason = targets.reason(entry);
            if (reason == null) { kept.add(entry); }
            else { report.append("\nHide ").append(MenuRules.plain(entry.getOption())).append(" — ").append(reason); }
        }
        if (kept.size() != entries.length)
        {
            menu.setMenuEntries(kept.toArray(new MenuEntry[0]));
            diagnostics = "Before: " + entries.length + " entries. After: " + kept.size() + " entries.\n" + report;
        }
    }
    private void cleanOpenedMenu(Menu menu,StringBuilder report,int depth)
    {
        if (depth > 8) { return; }
        MenuEntry[] entries = menu.getMenuEntries();
        List<MenuEntry> kept = new ArrayList<>(entries.length);
        MenuEntry cancel = null;
        for (MenuEntry entry : entries)
        {
            if (entry.getSubMenu() != null) { cleanOpenedMenu(entry.getSubMenu(),report,depth+1); }
            if (entry.getType() == MenuAction.CANCEL) { cancel = entry; }
            boolean hide = entry.getType() == MenuAction.CANCEL && config.hideCancel()
                || entry.getType() == MenuAction.WALK && config.hideWalkHere()
                || entry.getType() == MenuAction.SET_HEADING && config.hideSetHeading();
            if (!hide) { kept.add(entry); }
            else if (report.length() < 12000) { report.append("\nHide ").append(MenuRules.plain(entry.getOption())).append(" — right-click menu cleanup"); }
        }
        // Never turn Cancel into a default game action or leave an empty root menu.
        if (kept.isEmpty() && cancel != null) { kept.add(cancel); report.append("\nKeep Cancel — empty-menu fallback"); }
        if (kept.size() != entries.length) { menu.setMenuEntries(kept.toArray(new MenuEntry[0])); }
    }
    private void apply(Menu menu, String inheritedTarget, Context context, StringBuilder report, int depth, boolean preserveSwapAnchors)
    {
        if (depth > 8) { return; }
        MenuEntry[] entries = menu.getMenuEntries();
        List<MenuEntry> kept = new ArrayList<>(entries.length);
        for (MenuEntry entry : entries)
        {
            // Menu Entry Swapper discovers customization targets from native Examine
            // entries on MenuOpened. Keep both their identity and exact text until
            // its handler has run; our lower-priority open handler cleans up after it.
            if (preserveSwapAnchors && isSwapAnchor(entry))
            {
                ColorEdit edit = ownedColors.remove(entry);
                if (edit != null && edit.matches(entry)) { entry.setOption(edit.before); }
                kept.add(entry);
                continue;
            }
            String target = MenuRules.plain(entry.getTarget());
            if (target.isEmpty()) { target = inheritedTarget; }
            String option = MenuRules.plain(entry.getOption());
            String reason = reason(entry, entries, target, option, context);
            if (reason != null)
            {
                if (report.length() < 12000) { report.append("\nHide ").append(option).append(" ").append(target).append(" — ").append(reason); }
                continue;
            }
            if (entry.getSubMenu() != null) { apply(entry.getSubMenu(), target, context, report, depth + 1, preserveSwapAnchors); }
            if (config.enableColors())
            {
                String color = color(target, option);
                if (color != null)
                {
                    // Strip only color tags; retain images and other plugins' presentation markers.
                    ColorEdit prior = ownedColors.get(entry);
                    String before = prior != null && prior.after.equals(entry.getOption()) ? prior.before : entry.getOption();
                    String after = "<col=" + color + ">" + entry.getOption().replaceAll("</?col(?:=[^>]*)?>", "") + "</col>";
                    if (ownedColors.size() > 1024) { ownedColors.clear(); }
                    ownedColors.put(entry,new ColorEdit(before,after,entry));
                    entry.setOption(after);
                    if (report.length() < 12000) { report.append("\nColor ").append(option).append(" ").append(target).append(" #").append(color); }
                }
            }
            kept.add(entry);
        }
        // Do not remove one entry at a time: backed entry objects can be remapped on removal.
        if (kept.size() != entries.length) { menu.setMenuEntries(kept.toArray(new MenuEntry[0])); }
    }
    private static boolean isSwapAnchor(MenuEntry entry)
    {
        MenuAction type = entry.getType();
        if (type == MenuAction.EXAMINE_OBJECT || type == MenuAction.EXAMINE_NPC) { return true; }
        int group = entry.getParam1() >>> 16;
        return (type == MenuAction.CC_OP || type == MenuAction.CC_OP_LOW_PRIORITY)
            && (group == InterfaceID.INVENTORY || group == InterfaceID.WORNITEMS)
            && entry.getIdentifier() == 10
            && MenuRules.plain(entry.getOption()).equals("Examine");
    }
    String color(String target, String option)
    {
        for (MenuRules.Rule rule : colors) { if (rule.matches(target, option)) { return rule.color; } }
        return null;
    }
    boolean excepted(String target,boolean inventory,boolean bank,boolean ground)
    {
        for (MenuRules.Rule rule : exceptions) { if (rule.applies(inventory,bank,ground) && rule.matches(target,"")) { return true; } }
        return false;
    }
    String reason(MenuEntry entry, MenuEntry[] siblings, String target, String option, Context c)
    {
        MenuAction type = entry.getType();
        String targetReason = targets.reason(entry);
        if (targetReason != null) { return targetReason; }
        boolean item = isItem(entry);
        boolean inventory = item && inventoryGroup(entry);
        boolean ground = type == MenuAction.EXAMINE_ITEM_GROUND || type == MenuAction.GROUND_ITEM_FIRST_OPTION
            || type == MenuAction.GROUND_ITEM_SECOND_OPTION || type == MenuAction.GROUND_ITEM_THIRD_OPTION
            || type == MenuAction.GROUND_ITEM_FOURTH_OPTION || type == MenuAction.GROUND_ITEM_FIFTH_OPTION;
        if (excepted(target,inventory,c.bank,ground)) { return null; }
        if (inventory && c.bank)
        {
            if (option.equalsIgnoreCase("Wield") && config.bankWield()
                || option.equalsIgnoreCase("Wear") && config.bankWear()
                || option.equalsIgnoreCase("Drink") && config.bankDrink()
                || option.equalsIgnoreCase("Eat") && config.bankEat()) { return "bank protection"; }
        }
        if (inventory && config.potionEmpty() && option.equalsIgnoreCase("Empty") && target.matches(".*\\([1-9]\\)$"))
        { return "potion Empty protection"; }
        if (item)
        {
            for (MenuRules.Rule rule : itemRules) { if (rule.applies(inventory,c.bank,ground) && rule.matches(target, option)) { return "custom item rule (" + rule.context.name().toLowerCase(Locale.ROOT) + ")"; } }
        }
        if (type == MenuAction.EXAMINE_ITEM_GROUND && config.examineGround()) { return "ground Examine"; }
        if (item && option.equalsIgnoreCase("Examine") && type != MenuAction.EXAMINE_ITEM_GROUND && config.examineInventory()) { return "item Examine"; }
        if (type == MenuAction.EXAMINE_NPC && config.examineNpc()
            && !(config.keepLoneNpc() && loneExamine(entry, siblings))) { return "NPC Examine"; }
        if (type == MenuAction.EXAMINE_OBJECT && config.examineObject()
            && !(config.keepLoneObject() && loneExamine(entry, siblings))) { return "object Examine"; }
        // Temple Trekking swamp vines use a knife, and quest cave entrances may start dialogue.
        if (type == MenuAction.GAME_OBJECT_FIRST_OPTION && c.toolsKnown)
        {
            if (config.chop() && !c.axe
                && entry.getIdentifier() != net.runelite.api.gameval.ObjectID.TEMPLETREK_SWAMPTREE_SMALL_VINES
                && (option.startsWith("Chop") && (target.contains("ree") || ToolCatalog.CHOP.contains(target))
                || option.startsWith("Cut") && (target.contains("ree") || target.equals("Sulliuscep")))) { return "axe required"; }
            if (config.mine() && !c.pick && option.equals("Mine")
                && !target.equalsIgnoreCase("Cave entrance")) { return "pickaxe required"; }
        }
        if (OBJECTS.contains(type))
        {
            if (config.house() && c.house && !c.building && HomeCatalog.OPTIONS.contains(option)) { return "house building mode off"; }
            if (config.mahogany() && option.equals("Remove") && !c.house)
            {
                Integer broken = HomeCatalog.REPAIRS.get(entry.getIdentifier());
                if (broken != null)
                {
                    ObjectComposition object = client.getObjectDefinition(entry.getIdentifier());
                    ObjectComposition active = object != null && object.getImpostorIds() != null ? object.getImpostor() : null;
                    if (active != null && active.getId() != broken) { return "furniture does not need replacement"; }
                }
            }
        }
        return null;
    }
    static boolean isItem(MenuEntry entry)
    {
        if (!ITEMS.contains(entry.getType())) { return false; }
        switch (entry.getType())
        {
            case EXAMINE_ITEM_GROUND:
            case GROUND_ITEM_FIRST_OPTION: case GROUND_ITEM_SECOND_OPTION: case GROUND_ITEM_THIRD_OPTION:
            case GROUND_ITEM_FOURTH_OPTION: case GROUND_ITEM_FIFTH_OPTION: return true;
            default: return entry.getItemId() >= 0;
        }
    }
    static boolean inventoryGroup(MenuEntry entry)
    {
        int group = entry.getParam1() >>> 16;
        return group == InterfaceID.INVENTORY || group == InterfaceID.BANKSIDE;
    }
    private static boolean loneExamine(MenuEntry entry, MenuEntry[] entries)
    {
        for (MenuEntry other : entries)
        {
            if (other != entry && other.getIdentifier() == entry.getIdentifier()
                && other.getParam0() == entry.getParam0() && other.getParam1() == entry.getParam1()
                && MenuRules.plain(other.getTarget()).equals(MenuRules.plain(entry.getTarget()))
                && other.getType() != MenuAction.CANCEL && other.getType() != MenuAction.WALK
                && !MenuRules.plain(other.getOption()).equalsIgnoreCase("Examine")) { return false; }
        }
        return true;
    }
    private Context context()
    {
        Context c = new Context();
        Widget bank = client.getWidget(InterfaceID.BANKMAIN, 0);
        c.bank = bank != null && !bank.isHidden();
        ItemContainer inv = client.getItemContainer(InventoryID.INV);
        ItemContainer worn = client.getItemContainer(InventoryID.WORN);
        c.toolsKnown = inv != null && worn != null;
        if (c.toolsKnown)
        {
            for (ItemContainer container : new ItemContainer[]{inv, worn})
            {
                for (Item item : container.getItems())
                {
                    if (item.getQuantity() > 0) { c.axe |= ToolCatalog.AXES.contains(item.getId()); c.pick |= ToolCatalog.PICKS.contains(item.getId()); }
                }
            }
        }
        if (client.getLocalPlayer() != null && client.getTopLevelWorldView() != null && client.getTopLevelWorldView().isInstance())
        {
            WorldPoint point = WorldPoint.fromLocalInstance(client.getTopLevelWorldView().getScene(), client.getLocalPlayer().getLocalLocation(), client.getTopLevelWorldView().getPlane());
            c.house = point != null && HomeCatalog.REGIONS.contains(point.getRegionID());
        }
        c.building = c.house && client.getVarbitValue(VarbitID.POH_BUILDING_MODE) != 0;
        return c;
    }
    static final class Context { boolean bank, toolsKnown, axe, pick, house, building; }
    private static final class ColorEdit
    {
        final String before, colored, target;
        String after;
        final MenuAction type;
        final int identifier;
        ColorEdit(String before,String after,MenuEntry entry)
        { this.before=before; this.after=after; this.colored=after; target=MenuRules.plain(entry.getTarget()); type=entry.getType(); identifier=entry.getIdentifier(); }
        boolean matches(MenuEntry entry)
        { return entry.getOption().equals(after) && MenuRules.plain(entry.getTarget()).equals(target)
            && entry.getType() == type && entry.getIdentifier() == identifier; }
    }
}

