package com.improvedmenus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.components.TooltipComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/** Right-align only our row, leaving the shared tooltip stack owned by RuneLite. */
final class OptionCountTooltip extends TooltipComponent
{
    private final String text;
    private final TooltipManager manager;
    private final Client client;
    private Point location=new Point();

    OptionCountTooltip(String text,TooltipManager manager,Client client,Color background)
    {
        this.text=text; this.manager=manager; this.client=client;
        setText(text);
        if (background!=null) { setBackgroundColor(background); }
    }

    @Override public void setPreferredLocation(Point point) { location=new Point(point); }

    @Override public Dimension render(Graphics2D graphics)
    {
        // Measure using RuneLite's own text/tag sizing, without painting or rendering
        // another plugin's component (which could have side effects).
        Graphics2D measuring=(Graphics2D)graphics.create();
        Dimension own;
        int width;
        try
        {
            measuring.setClip(0,0,0,0);
            TooltipComponent measure=new TooltipComponent();
            measure.setText(text); own=measure.render(measuring); width=own.width;
            for (Tooltip tooltip : manager.getTooltips())
            {
                if (tooltip.getText()!=null)
                {
                    measure.setText(tooltip.getText()); width=Math.max(width,measure.render(measuring).width);
                }
                else if (tooltip.getComponent()!=null && tooltip.getComponent()!=this)
                {
                    Rectangle bounds=tooltip.getComponent().getBounds();
                    if (bounds!=null) { width=Math.max(width,bounds.width); }
                }
            }
        }
        finally { measuring.dispose(); }
        int x=Math.max(0,Math.min(location.x+width-own.width,client.getCanvasWidth()-own.width));
        int y=Math.max(0,Math.min(location.y,client.getCanvasHeight()-own.height));
        super.setPreferredLocation(new Point(x,y));
        super.render(graphics);
        return new Dimension(width,own.height);
    }
}

package com.improvedmenus;

import javax.swing.AbstractButton;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JLabel;

/** User-authored names are text, never Swing HTML or image resources. */
final class PlainText
{
    private PlainText() { }
    static void set(JLabel label, String text)
    {
        label.putClientProperty("html.disable", Boolean.TRUE);
        label.setText(text);
    }
    static void set(AbstractButton button, String text)
    {
        button.putClientProperty("html.disable", Boolean.TRUE);
        button.setText(text);
    }
    static DefaultListCellRenderer renderer()
    {
        DefaultListCellRenderer renderer = new DefaultListCellRenderer();
        renderer.putClientProperty("html.disable", Boolean.TRUE);
        return renderer;
    }
}

package com.improvedmenus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.FriendsChatRank;
import net.runelite.api.IndexedSprite;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.party.PartyService;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/** Adds cosmetic badges to opened player menus; never changes a native action or its priority. */
@Singleton
final class PlayerMenuBadges extends Overlay
{
    private final Client client;
    private final ImprovedMenusConfig config;
    private final ChatIconManager icons;
    private final PartyService party;
    private static final Pattern IMAGE = Pattern.compile("<img=(\\d+)>");
    private final TooltipManager tooltips;
    private final int[] registrations = {-1, -1, -1, -1};
    private final Map<MenuEntry, Edit> edits = new IdentityHashMap<>();
    private final Map<MenuEntry, String> copies = new IdentityHashMap<>();
    private Menu copyMenu;
    private boolean active;
    private int generation;
    Consumer<String> clipboard = PlayerMenuBadges::copyToClipboard;

    @Inject
    PlayerMenuBadges(Client client, ImprovedMenusConfig config, ChatIconManager icons,
        PartyService party, TooltipManager tooltips)
    {
        this.client = client;
        this.config = config;
        this.icons = icons;
        this.party = party;
        this.tooltips = tooltips;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
    }

    void start()
    {
        active = true;
        // ChatIconManager has no unregister method. Reuse these four registrations after re-enable.
        for (int i = 0; i < registrations.length; i++)
            if (registrations[i] == -1) registrations[i] = icons.registerChatIcon(image(i));
    }

    void shutdown() { active = false; clear(); }

    void clear()
    {
        generation++;
        edits.forEach((entry, edit) -> { if (edit.matches(entry)) entry.setTarget(edit.original); });
        edits.clear();
        if (copyMenu != null)
        {
            for (Map.Entry<MenuEntry, String> copy : copies.entrySet())
            {
                MenuEntry entry = copy.getKey();
                if (entry.getType() == MenuAction.RUNELITE && "Copy name".equals(entry.getOption())
                    && copy.getValue().equals(entry.getTarget())) copyMenu.removeMenuEntry(entry);
            }
        }
        copies.clear();
        copyMenu = null;
    }

    void decorate(Menu menu)
    {
        clear();
        if (!active || menu == null) return;
        Map<String, String> players = new LinkedHashMap<>();
        MenuEntry[] entries = menu.getMenuEntries();
        for (MenuEntry entry : entries)
        {
            Player player = entry.getPlayer();
            if (player == null || player.getName() == null || entry.getTarget() == null) continue;
            String name = MenuRules.plain(player.getName()).replace('\u00a0', ' ');
            String key = normalized(name);
            if (key.isEmpty()) continue;
            players.putIfAbsent(key, name);
            String target = entry.getTarget();
            StringBuilder prefix = new StringBuilder();
            List<String> labels = new ArrayList<>();
            if (config.playerFriendBadge() && player.isFriend()) add(0, "Friend", target, prefix, labels);
            if (config.playerIgnoreBadge() && client.getIgnoreContainer() != null
                && client.getIgnoreContainer().findByName(name) != null) add(1, "Ignored", target, prefix, labels);
            if (config.playerFriendsChatBadge() && player.isFriendsChatMember() && !hasFriendsChatRank(target))
                add(2, "Friends Chat member", target, prefix, labels);
            if (config.playerPartyBadge() && party.isInParty() && party.getMemberByDisplayName(name) != null)
                add(3, "RuneLite party member", target, prefix, labels);
            if (prefix.length() == 0) continue;
            String decorated = prefix + target;
            edits.put(entry, new Edit(entry, target, decorated, String.join("<br>", labels)));
            entry.setTarget(decorated);
        }
        if (!config.playerCopyName()) return;
        copyMenu = menu;
        int callbackGeneration = generation;
        players.forEach((key, name) -> {
            boolean exists = Arrays.stream(entries).anyMatch(e ->
                ("Copy name".equalsIgnoreCase(MenuRules.plain(e.getOption()))
                    || "Copy player name".equalsIgnoreCase(MenuRules.plain(e.getOption())))
                    && key.equals(normalized(e.getTarget())));
            if (exists) return;
            MenuEntry copy = menu.createMenuEntry(0).setOption("Copy name").setTarget(name).setType(MenuAction.RUNELITE)
                .onClick(e -> { if (active && generation == callbackGeneration && config.playerCopyName()) clipboard.accept(name); });
            copies.put(copy, name);
        });
    }

    private void add(int kind, String label, String target, StringBuilder prefix, List<String> labels)
    {
        int index = icons.chatIconIndex(registrations[kind]);
        if (index < 0 || containsIcon(target, index)) return;
        prefix.append("<img=").append(index).append('>');
        labels.add(label);
    }

    private boolean hasFriendsChatRank(String target)
    {
        for (FriendsChatRank rank : FriendsChatRank.values())
        {
            if (rank != FriendsChatRank.UNRANKED)
            {
                int index = icons.getIconNumber(rank);
                if (index >= 0 && containsIcon(target, index)) return true;
            }
        }
        return false;
    }

    private static String normalized(String value)
    {
        if (value == null) return "";
        String name = MenuRules.plain(value).replace('\u00a0', ' ').replace('_', ' ').trim().toLowerCase(Locale.ROOT);
        return name.matches("[a-z0-9 -]{1,12}") ? name : "";
    }

    private boolean containsIcon(String target, int expected)
    {
        IndexedSprite[] sprites = client.getModIcons();
        Matcher matcher = IMAGE.matcher(target);
        while (matcher.find())
        {
            if (matcher.group(1).length() > 8) continue;
            int found = Integer.parseInt(matcher.group(1));
            if (found == expected) return true;
            // Other plugins may register the same image under a different index.
            if (sprites != null && found < sprites.length && expected < sprites.length
                && sameImage(sprites[found], sprites[expected])) return true;
        }
        return false;
    }

    static boolean sameImage(IndexedSprite a, IndexedSprite b)
    {
        if (a == null || b == null || a.getWidth() != b.getWidth() || a.getHeight() != b.getHeight()
            || a.getOffsetX() != b.getOffsetX() || a.getOffsetY() != b.getOffsetY()) return false;
        byte[] ap = a.getPixels(), bp = b.getPixels();
        int[] ac = a.getPalette(), bc = b.getPalette();
        if (ap == null || bp == null || ac == null || bc == null || ap.length == 0 || ap.length != bp.length) return false;
        boolean visible = false;
        for (int i = 0; i < ap.length; i++)
        {
            int ai = ap[i] & 255, bi = bp[i] & 255;
            if (ai >= ac.length || bi >= bc.length || (ai == 0) != (bi == 0) || (ai != 0 && ac[ai] != bc[bi])) return false;
            visible |= ai != 0;
        }
        return visible;
    }

    @Override public Dimension render(Graphics2D graphics)
    {
        if (!active || !client.isMenuOpen()) return null;
        Menu menu = client.getMenu();
        if (menu == null) return null;
        int x = client.getMouseCanvasPosition().getX(), y = client.getMouseCanvasPosition().getY();
        if (x < menu.getMenuX() || x >= menu.getMenuX() + menu.getMenuWidth()) return null;
        MenuEntry[] entries = menu.getMenuEntries();
        int scroll = client.isMenuScrollable() ? client.getMenuScroll() : 0;
        for (int i = 0; i < entries.length; i++)
        {
            int top = menu.getMenuY() + 19 + (entries.length - 1 - i - scroll) * 15;
            if (top < menu.getMenuY() + 19 || top + 15 > menu.getMenuY() + menu.getMenuHeight()) continue;
            Edit edit = edits.get(entries[i]);
            if (y >= top && y < top + 15 && edit != null && edit.matches(entries[i]))
                tooltips.add(new Tooltip(edit.label));
        }
        return null;
    }

    static BufferedImage image(int kind)
    {
        BufferedImage image = new BufferedImage(11, 11, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        Color dark = new Color(25, 35, 30);
        if (kind == 0)
        {
            g.setColor(dark); g.fillOval(0, 0, 11, 11);
            g.setColor(new Color(83, 215, 119)); g.fillOval(1, 1, 9, 9);
            g.setColor(dark); g.fillRect(3, 3, 1, 2); g.fillRect(7, 3, 1, 2);
            g.drawLine(3, 6, 4, 7); g.drawLine(4, 7, 6, 7); g.drawLine(6, 7, 7, 6);
        }
        else if (kind == 1)
        {
            g.setColor(dark); g.fillOval(0, 0, 11, 11);
            g.setColor(new Color(239, 112, 112)); g.fillOval(1, 1, 9, 9);
            g.setColor(dark); g.fillRect(3, 5, 5, 2);
        }
        else if (kind == 2)
        {
            g.setColor(dark); g.fillRect(0, 1, 11, 8); g.fillRect(2, 8, 3, 3);
            g.setColor(new Color(104, 211, 234)); g.fillRect(1, 2, 9, 6); g.fillRect(3, 8, 1, 2);
            g.setColor(dark); g.drawLine(3, 4, 7, 4); g.drawLine(3, 6, 6, 6);
        }
        else
        {
            g.setColor(dark); g.fillOval(0, 0, 6, 6); g.fillOval(5, 1, 6, 6); g.fillRect(0, 5, 11, 6);
            g.setColor(new Color(190, 150, 255)); g.fillOval(1, 1, 4, 4); g.fillOval(6, 2, 4, 4);
            g.fillRect(1, 6, 4, 4); g.fillRect(6, 7, 4, 3);
        }
        g.dispose();
        return image;
    }

    private static void copyToClipboard(String name)
    {
        SwingUtilities.invokeLater(() -> {
            try { Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(name), null); }
            catch (IllegalStateException ex)
            { JOptionPane.showMessageDialog(null, "The clipboard is busy. Please try Copy name again.", "Improved Right-Clicks", JOptionPane.INFORMATION_MESSAGE); }
        });
    }

    private static final class Edit
    {
        final String original, decorated, label, option;
        final MenuAction type;
        final int identifier, param0, param1, worldView;
        Edit(MenuEntry entry, String original, String decorated, String label)
        {
            this.original = original; this.decorated = decorated; this.label = label;
            option = entry.getOption(); type = entry.getType(); identifier = entry.getIdentifier();
            param0 = entry.getParam0(); param1 = entry.getParam1(); worldView = entry.getWorldViewId();
        }
        boolean matches(MenuEntry entry)
        {
            // Our hover colors can change the option before badges are restored or refreshed.
            return decorated.equals(entry.getTarget()) && MenuRules.plain(option).equals(MenuRules.plain(entry.getOption())) && entry.getType() == type
                && entry.getIdentifier() == identifier && entry.getParam0() == param0 && entry.getParam1() == param1
                && entry.getWorldViewId() == worldView;
        }
    }
}

package com.improvedmenus;

import com.google.gson.*;
import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
final class ProfileStore
{
    @Inject private ConfigManager manager;
    @Inject private Gson gson;
    private final Deque<Edit> undo = new ArrayDeque<>();
    static final String PROFILE_KEY = "savedProfiles";
    static final int MAX_JSON = 100000;

    String value(SettingsCatalog.Setting setting)
    {
        String value = manager.getConfiguration(ImprovedMenusConfig.GROUP, setting.key);
        return value == null ? setting.defaultValue : value;
    }
    Map<String,String> snapshot()
    {
        Map<String,String> result = new LinkedHashMap<>();
        for (SettingsCatalog.Setting setting : SettingsCatalog.ALL.values()) { result.put(setting.key, value(setting)); }
        return result;
    }
    synchronized void apply(Map<String,String> settings)
    {
        validate(settings);
        Map<String,String> before = new LinkedHashMap<>();
        Map<String,String> after = new LinkedHashMap<>();
        settings.forEach((key,next) -> {
            String current = value(SettingsCatalog.ALL.get(key));
            if (!current.equals(next)) { before.put(key,current); after.put(key,next); }
        });
        if (after.isEmpty()) { return; }
        undo.addLast(new Edit(before,after));
        if (undo.size() > 20) { undo.removeFirst(); }
        write(after);
    }
    private void write(Map<String,String> settings)
    {
        settings.forEach((key,value) -> manager.setConfiguration(ImprovedMenusConfig.GROUP,key,value));
    }
    synchronized boolean undo()
    {
        if (undo.isEmpty()) { return false; }
        Edit edit = undo.removeLast();
        Map<String,String> restore = new LinkedHashMap<>();
        edit.before.forEach((key,previous) -> {
            // Preserve subsequent edits made through RuneLite or another plugin.
            if (value(SettingsCatalog.ALL.get(key)).equals(edit.after.get(key))) { restore.put(key,previous); }
        });
        write(restore); return true;
    }
    private static final class Edit
    {
        final Map<String,String> before;
        final Map<String,String> after;
        Edit(Map<String,String> before,Map<String,String> after) { this.before=before; this.after=after; }
    }
    synchronized void clearHistory() { undo.clear(); }
    static void validate(Map<String,String> settings)
    {
        if (settings == null || settings.size() > SettingsCatalog.ALL.size()) { throw new IllegalArgumentException("Invalid settings"); }
        settings.forEach((key,value) -> {
            SettingsCatalog.Setting s = SettingsCatalog.ALL.get(key);
            if (s == null) { throw new IllegalArgumentException("Unknown setting: " + key); }
            s.validate(value);
        });
    }
    String exportSettings(Map<String,String> settings)
    {
        validate(settings);
        JsonObject root = new JsonObject(); root.addProperty("version",1);
        root.add("settings",gson.toJsonTree(settings));
        return gson.toJson(root);
    }
    Map<String,String> previewImport(String json)
    {
        if (json == null || json.length() > MAX_JSON) { throw new IllegalArgumentException("Import is too large"); }
        try
        {
            JsonObject root = gson.fromJson(json, JsonObject.class);
            if (root == null || root.size() != 2 || !root.has("version")
                || !root.get("version").isJsonPrimitive() || !root.getAsJsonPrimitive("version").isNumber()
                || root.get("version").getAsBigDecimal().compareTo(java.math.BigDecimal.ONE) != 0
                || !root.has("settings") || !root.get("settings").isJsonObject())
            { throw new IllegalArgumentException("Unsupported profile version or format"); }
            JsonObject settings = root.getAsJsonObject("settings");
            Map<String,String> result = new LinkedHashMap<>();
            for (Map.Entry<String,JsonElement> entry : settings.entrySet())
            {
                if (!entry.getValue().isJsonPrimitive() || !entry.getValue().getAsJsonPrimitive().isString())
                { throw new IllegalArgumentException("Setting values must be strings"); }
                // Older profiles may contain the retired account-helmet switches.
                if ("playerIronmanBadge".equals(entry.getKey()) || "playerHiscores".equals(entry.getKey())) continue;
                result.put(entry.getKey(),entry.getValue().getAsString());
            }
            validate(result); return result;
        }
        catch (JsonParseException | IllegalStateException | ClassCastException | NumberFormatException e) { throw new IllegalArgumentException("Invalid profile JSON",e); }
    }
    private JsonObject profiles()
    {
        String raw = manager.getConfiguration(ImprovedMenusConfig.GROUP, PROFILE_KEY);
        if (raw == null) { return new JsonObject(); }
        try
        {
            if (raw.length() > MAX_JSON * 20) { return new JsonObject(); }
            JsonObject result = gson.fromJson(raw, JsonObject.class);
            return result == null ? new JsonObject() : result;
        }
        catch (JsonParseException e) { return new JsonObject(); }
    }
    List<String> names() { return new ArrayList<>(profiles().keySet()); }
    synchronized void save(String name)
    {
        name = name.trim();
        if (name.isEmpty() || name.length() > 40) { throw new IllegalArgumentException("Use a profile name of 1–40 characters"); }
        JsonObject profiles = profiles();
        if (profiles.size() >= 20 && !profiles.has(name)) { throw new IllegalArgumentException("At most 20 profiles are allowed"); }
        profiles.addProperty(name,exportSettings(snapshot()));
        manager.setConfiguration(ImprovedMenusConfig.GROUP,PROFILE_KEY,gson.toJson(profiles));
    }
    Map<String,String> load(String name)
    {
        JsonElement profile = profiles().get(name);
        if (profile == null || !profile.isJsonPrimitive()) { throw new IllegalArgumentException("Profile not found"); }
        return previewImport(profile.getAsString());
    }
    Map<String,String> legacyPreview(String source)
    {
        Map<String,String> result = new LinkedHashMap<>();
        switch (source)
        {
            case "No Examine":
                legacy(result,"noexamine","examineItemGround","examineGround");
                legacy(result,"noexamine","examineItemsInventory","examineInventory");
                legacy(result,"noexamine","examineNpcs","examineNpc");
                legacy(result,"noexamine","examineObjects","examineObject");
                legacy(result,"noexamine","keepLonelyExamineNpcs","keepLoneNpc");
                legacy(result,"noexamine","keepLonelyExamineObjects","keepLoneObject");
                legacy(result,"noexamine","cancelEverywhere","hideCancel");
                legacy(result,"noexamine","walkHereEverywhere","hideWalkHere");
                legacy(result,"noexamine","setHeadingEverywhere","hideSetHeading"); break;
            case "No Use Player": legacy(result,"no-use-player","whitelistItemsString","playerUseItems"); break;
            case "Don't Telegrab NPCs": legacy(result,"donttelegrabnpcs","telegrabWhitelist","telegrabNpcNames"); break;
            case "No Misclicks In Bank":
                legacy(result,"nowieldinbank","hideWield","bankWield"); legacy(result,"nowieldinbank","hideWear","bankWear");
                legacy(result,"nowieldinbank","hideDrink","bankDrink"); legacy(result,"nowieldinbank","hideEat","bankEat"); break;
            case "Item Option Hider": legacy(result,"itemoptionhider","hides","itemRules"); break;
            case "Menu Colorizer":
                legacy(result,"menucolorizer","colorMappings","colors"); legacy(result,"menucolorizer","enableColoring","enableColors");
                legacy(result,"menucolorizer","showTagOptions","colorPicker");
                legacyColor(result,"menucolorizer","defaultPickerColor","defaultPickerColor"); break;
            case "Mouseover Options+":
                legacy(result,"mouseoveroptions","minimumOptions","minimumOptions");
                legacy(result,"mouseoveroptions","includeExamine","countExamine");
                legacy(result,"mouseoveroptions","showOnWidgets","countOnWidgets");
                legacyColor(result,"mouseoveroptions","textColor","optionCountColor"); break;
            case "Tool Required": legacy(result,"tool-required","chopDown","chop"); legacy(result,"tool-required","mine","mine"); break;
            case "Misclick Guard":
                for (String key : Arrays.asList("autoRetaliate","xpDrops","alwaysSetPlaceholders","report","deprioritizeLeftClickOffEntries"))
                { legacy(result,"misclick-guard",key,key); } break;
            default: throw new IllegalArgumentException("Select a supported source");
        }
        validate(result); return result;
    }
    private void legacy(Map<String,String> result,String group,String oldKey,String key)
    {
        String raw = manager.getConfiguration(group,oldKey);
        if (raw != null) { result.put(key,raw); }
    }
    private void legacyColor(Map<String,String> result,String group,String oldKey,String key)
    {
        String raw=manager.getConfiguration(group,oldKey);
        if (raw == null) { return; }
        try { result.put(key,String.format("#%06x",java.awt.Color.decode(raw).getRGB() & 0xffffff)); }
        catch (NumberFormatException e) { throw new IllegalArgumentException("Invalid saved color for " + oldKey); }
    }
}

package com.improvedmenus;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;

@Singleton
final class ReleaseNotesNotice
{
    static final String RELEASE = "2026-10-29-persistent-player-badges";
    static final String KEY = "recentChangesSeen";
    private final Client client;
    private final ClientThread thread;
    private final ConfigManager config;
    private final ChatMessageManager chat;
    private volatile boolean active;
    private volatile int generation;

    @Inject ReleaseNotesNotice(Client client, ClientThread thread, ConfigManager config, ChatMessageManager chat)
    { this.client = client; this.thread = thread; this.config = config; this.chat = chat; }

    void startUp()
    {
        active = true;
        int request = ++generation;
        thread.invokeLater(() -> { if (request == generation) showIfLoggedIn(); });
    }
    void shutDown() { active = false; generation++; }
    void showIfLoggedIn()
    {
        if (!active || client.getGameState() != GameState.LOGGED_IN
            || RELEASE.equals(config.getConfiguration(ImprovedMenusConfig.GROUP, KEY))) return;
        chat.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE).value(
            "Improved Right-Clicks: Ironman helmets and Hiscores lookups have been removed. Friend, ignore, Friends Chat and party badges remain individually toggleable, alongside Copy name. Older saved profiles still load their remaining settings. Existing player icons and colors are preserved.").build());
        config.setConfiguration(ImprovedMenusConfig.GROUP, KEY, RELEASE);
    }
}

package com.improvedmenus;

import javax.inject.Inject;
