@Singleton
final class RenameNotice
{
    static final String KEY = "rightClicksRenameNoticeShown";
    private final Client client;
    private final ClientThread clientThread;
    private final ConfigManager config;
    private final ChatMessageManager chat;
    private volatile boolean active;

    @Inject
    RenameNotice(Client client, ClientThread clientThread, ConfigManager config, ChatMessageManager chat)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.config = config;
        this.chat = chat;
    }

    void startUp()
    {
        active = true;
        clientThread.invokeLater(this::showIfLoggedIn);
    }

    void shutDown()
    {
        active = false;
    }

    void showIfLoggedIn()
    {
        if (!active || client.getGameState() != GameState.LOGGED_IN
            || Boolean.parseBoolean(config.getConfiguration(ImprovedMenusConfig.GROUP, KEY)))
        {
            return;
        }
        chat.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE)
            .value("Menu Workshop is now Improved Right-Clicks. Your saved settings and profiles are unchanged. Find us under the new name in plugin settings.")
            .build());
        config.setConfiguration(ImprovedMenusConfig.GROUP, KEY, "true");
    }
}

package com.improvedmenus;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;

@Singleton
final class RevealState
{
    @Inject private Client client;
    @Inject private ImprovedMenusConfig config;

    boolean isRevealed()
    {
        if (config.revealKey() == ImprovedMenusConfig.RevealKey.NONE
            || client.getCanvas() == null || !client.getCanvas().hasFocus()) { return false; }
        switch (config.revealKey())
        {
            case CONTROL: return client.isKeyPressed(KeyCode.KC_CONTROL);
            case SHIFT: return client.isKeyPressed(KeyCode.KC_SHIFT);
            case ALT: return client.isKeyPressed(KeyCode.KC_ALT);
            default: return false;
        }
    }
}

package com.improvedmenus;

import java.util.*;

/** Explicit editable keys. Profiles cannot set unrelated RuneLite configuration. */
final class SettingsCatalog
{
    static final class Setting
    {
        final String key, label, section, defaultValue;
        final String[] choices;
        Setting(String key, String label, String section, String defaultValue, String... choices)
        { this.key=key; this.label=label; this.section=section; this.defaultValue=defaultValue; this.choices=choices; }
        void validate(String value)
        {
            if (value == null) { throw new IllegalArgumentException("Missing value for " + label); }
            if (choices.length != 0 && !Arrays.asList(choices).contains(value)) { throw new IllegalArgumentException("Invalid value for " + label); }
            if (key.equals("itemRules")) { MenuRules.parseItems(value); }
            else if (key.equals("colors")) { MenuRules.parseColors(value); }
            else if (key.equals("exceptions")) { MenuRules.parseExceptions(value); }
            else if (key.equals("defaultPickerColor") || key.equals("optionCountColor"))
            { if (!value.matches("#[0-9a-fA-F]{6}")) { throw new IllegalArgumentException("Use #RRGGBB for " + label); } }
            else if (key.equals("minimumOptions"))
            {
                try { int count=Integer.parseInt(value); if (count < 1 || count > 500) { throw new NumberFormatException(); } }
                catch (NumberFormatException e) { throw new IllegalArgumentException("Use a whole number from 1 to 500 for " + label); }
            }
            else if (choices.length == 0) { MenuRules.bounded(value); }
        }
    }
