  String source="#define FOOD(name_) (name:name_)\n#define STYLE icon=Sprite(41,0);\napply (true) {icon=Item(995);} rule (FOOD(\"Shark\") && quantity:>=2) { STYLE } rule (true) {icon=CurrentItem();}";
